1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound  = errors.New("device not found")
12		ErrBatchConflict   = errors.New("batch conflicts with stored events")
13		ErrRuleNotFound    = errors.New("rule not found")
14		ErrAlertNotFound   = errors.New("alert not found")
15		ErrRuleConflict    = errors.New("rule already exists")
16		ErrVersionConflict = errors.New("rule version conflict")
17		ErrInvalidRule     = errors.New("invalid rule")
18		// ErrHistoryGone means a continuation cursor's start record was trimmed by
19		// the retention limit before the next page was read.
20		ErrHistoryGone = errors.New("cursor start no longer retained")
21	)
22	
23	// maxRetentionEvents bounds a per-device history retention setting.
24	const maxRetentionEvents = 10000
25	
26	// RetentionStatus reports a device's history retention settings and counters.
27	// MaxEvents 0 means unlimited. EarliestSequence is nil for an empty history;
28	// MaxSequence is the highest sequence ever received (0 before any sample) and
29	// never retreats, even after trimming.
30	type RetentionStatus struct {
31		MaxEvents        int64  `json:"maxEvents"`
32		RetainedEvents   int64  `json:"retainedEvents"`
33		EarliestSequence *int64 `json:"earliestSequence"`
34		MaxSequence      int64  `json:"maxSequence"`
35	}
36	
37	// Rule is a per-device threshold rule. It judges only samples accepted while
38	// enabled; it never backfills history. Device and ID are immutable after
39	// creation. Version starts at 1 and bumps on every successful update.
40	type Rule struct {
41		ID        string    `json:"id"`
42		Metric    string    `json:"metric"`
43		Trigger   float64   `json:"trigger"`
44		Recover   float64   `json:"recover"`
45		Enabled   bool      `json:"enabled"`
46		Version   int64     `json:"version"`
47		CreatedAt time.Time `json:"createdAt"`
48		UpdatedAt time.Time `json:"updatedAt"`
49	}
50	
51	// Alert is one threshold crossing. It retains the rule version and the
52	// metric/thresholds in force when it fired. A natural recovery records the
53	// recovery sample's sequence, value and observed time; an end caused by a rule
54	// update records the server time and reason instead.
55	type Alert struct {
56		ID                int64      `json:"id"`
57		RuleID            string     `json:"ruleId"`
58		RuleVersion       int64      `json:"ruleVersion"`
59		Metric            string     `json:"metric"`
60		Trigger           float64    `json:"trigger"`
61		Recover           float64    `json:"recover"`
62		Status            string     `json:"status"` // "active" | "ended"
63		TriggerSequence   int64      `json:"triggerSequence"`
64		TriggerValue      float64    `json:"triggerValue"`
65		TriggerObservedAt time.Time  `json:"triggerObservedAt"`
66		RecoverSequence   *int64     `json:"recoverSequence,omitempty"`
67		RecoverValue      *float64   `json:"recoverValue,omitempty"`
68		RecoverObservedAt *time.Time `json:"recoverObservedAt,omitempty"`
69		EndedAt           *time.Time `json:"endedAt,omitempty"`
70		EndReason         string     `json:"endReason,omitempty"` // "recovered" | "rule_changed"
71		AcknowledgedAt    *time.Time `json:"acknowledgedAt,omitempty"`
72	}
73	
74	const (
75		alertStatusActive    = "active"
76		alertStatusEnded     = "ended"
77		endReasonRecovered   = "recovered"
78		endReasonRuleChanged = "rule_changed"
79	)
80	
81	// ruleState pairs a rule with the id of its currently active alert (0 when
82	// none).
83	type ruleState struct {
84		rule          Rule
85		activeAlertID int64
86	}
