96	// Event is a single telemetry sample retained in a device's history.
97	type Event struct {
98		Sequence   int64              `json:"sequence"`
99		ObservedAt time.Time          `json:"observedAt"`
100		Values     map[string]float64 `json:"values"`
101	}
102	
103	// Sample is one replayed sample, decoded from the replay request body.
104	type Sample struct {
105		EventID    string
106		ObservedAt time.Time
107		Values     map[string]float64
108	}
109	
110	// ReplayReceipt summarises the outcome of a replay batch.
111	type ReplayReceipt struct {
112		BatchID      string         `json:"batchId"`
113		NewCount     int            `json:"newCount"`
114		Duplicate    int            `json:"duplicateCount"`
115		SampleStatus []SampleStatus `json:"samples"`
116	}
117	
118	// SampleStatus reports the history sequence assigned to (or reused by) a sample.
119	type SampleStatus struct {
120		EventID   string `json:"eventId"`
121		Sequence  int64  `json:"sequence"`
122		Duplicate bool   `json:"duplicate"`
123	}
124	
125	// HistoryFilter narrows a history query by observed-time range. Zero times mean
126	// the bound is open.
127	type HistoryFilter struct {
128		From time.Time
129		To   time.Time
130	}
131	
132	// StoredBatch records the ordered samples an accepted batchId committed along
133	// with the receipt returned on first acceptance, so a repeated batchId can be
134	// checked for identical content and replayed with the original receipt.
135	type storedBatch struct {
136		samples []Sample
137		receipt ReplayReceipt
138	}
139	
140	// knownSample is the durable replay-deduplication record for one eventId. It is
141	// retained even after the event itself leaves history through the retention
142	// limit, so a trimmed sample re-submitted later is still recognised as a
143	// duplicate (same content) or a conflict (different content).
144	type knownSample struct {
145		sequence   int64
146		observedAt time.Time
147		values     map[string]float64
148	}
149	
150	type deviceState struct {
151		device         Device
152		events         []Event                // retained history, ascending sequence (events[i].Sequence = eventBase + i + 1)
153		eventBase      int64                  // number of oldest events removed by retention; sequence of events[0] is eventBase+1
154		maxEvents      int64                  // retention cap; 0 means unlimited
155		known          map[string]knownSample // eventId -> first sample ever received (survives trimming)
156		batches        map[string]storedBatch
157		rules          map[string]*ruleState
158		alerts         []*Alert // per-device, ordered by alert id (id = index + 1)
159		config         *configState
160		tasks          []*taskState          // per-device, ordered by task id (id = index + 1)
161		tasksByRequest map[string]*taskState // requestId -> first task
162	}
163	
164	// maxSequence is the highest receive sequence ever assigned to the device. It
165	// never retreats: trimming removes events but keeps consuming nothing, and new
166	// samples continue after it.
167	func (state *deviceState) maxSequence() int64 {
168		return state.eventBase + int64(len(state.events))
169	}
170	
171	// earliestSequence returns the first currently retained sequence, or 0 when
172	// the history is empty.
173	func (state *deviceState) earliestSequence() int64 {
174		if len(state.events) == 0 {
175			return 0
176		}
177		return state.eventBase + 1
178	}
179	
180	// retentionStatus snapshots the retention view of the device.
181	func (state *deviceState) retentionStatus() RetentionStatus {
182		status := RetentionStatus{
183			MaxEvents:      state.maxEvents,
184			RetainedEvents: int64(len(state.events)),
185			MaxSequence:    state.maxSequence(),
186		}
187		if earliest := state.earliestSequence(); earliest != 0 {
188			status.EarliestSequence = &earliest
189		}
190		return status
191	}
192	
193	// planTrimThrough reports the cumulative count of oldest events that must be
194	// removed for the history to satisfy maxEvents after a write that leaves
195	// maxSequence at maxSeq. It only grows: raising the limit or going unlimited
196	// never brings trimmed events back.
197	func planTrimThrough(eventBase, maxSeq, maxEvents int64) int64 {
198		if maxEvents == 0 {
199			return eventBase
200		}
201		if through := maxSeq - maxEvents; through > eventBase {
202			return through
203		}
204		return eventBase
205	}
206	
207	// applyTrim drops oldest retained events through sequence trimThrough. It
208	// touches neither deduplication records nor any other device state.
209	func (state *deviceState) applyTrim(trimThrough int64) {
210		if trimThrough <= state.eventBase {
211			return
212		}
213		drop := trimThrough - state.eventBase
214		if drop > int64(len(state.events)) {
215			drop = int64(len(state.events))
216		}
217		// Drop the prefix without preserving its backing slots.
218		remaining := make([]Event, len(state.events)-int(drop))
219		copy(remaining, state.events[drop:])
220		state.events = remaining
221		state.eventBase += drop
222	}
223	
224	type Store struct {
225		mu      sync.RWMutex
226		devices map[string]*deviceState
227		now     func() time.Time
228	
229		// wal is nil in memory mode. When set, every mutation is appended and
230		// synced here before in-memory state changes or success is returned.
231		wal walSink
232		iid []byte // data-directory instance id bound into history cursors
233	}
234	
235	func NewStore() *Store {
236		return &Store{devices: make(map[string]*deviceState), now: time.Now}
237	}
238	
239	// instanceID identifies the backing data directory; cursors are scoped to it.
240	// It is nil in memory mode.
241	func (s *Store) instanceID() []byte {
242		s.mu.RLock()
243		defer s.mu.RUnlock()
244		return s.iid
245	}
246	
247	// Exists reports whether a device is registered.
248	func (s *Store) Exists(id string) bool {
249		s.mu.RLock()
250		defer s.mu.RUnlock()
251		_, ok := s.devices[id]
252		return ok
253	}
254	
255	func (s *Store) Register(id, site string) (Device, bool, error) {
256		s.mu.Lock()
257		defer s.mu.Unlock()
258		if state, ok := s.devices[id]; ok {
259			return cloneDevice(state.device), false, nil
260		}
261		now := s.now().UTC()
262		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
263		if s.wal != nil {
264			if err := s.wal.appendRecord(recRegister, walRegister{
265				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
266			}); err != nil {
267				return Device{}, false, storageUnavailable(err)
268			}
269		}
270		s.devices[id] = &deviceState{
271			device:  device,
272			known:   make(map[string]knownSample),
273			batches: make(map[string]storedBatch),
274			rules:   make(map[string]*ruleState),
275		}
276		return cloneDevice(device), true, nil
277	}
278	
279	// GetRetention returns the device's retention limit and history counters.
280	func (s *Store) GetRetention(id string) (RetentionStatus, error) {
281		s.mu.RLock()
282		defer s.mu.RUnlock()
283		state, ok := s.devices[id]
284		if !ok {
285			return RetentionStatus{}, ErrDeviceNotFound
286		}
287		return state.retentionStatus(), nil
288	}
289	
290	// SetRetention changes the per-device history cap. A maxEvents of 0 removes
291	// the limit; values 1..maxRetentionEvents keep at most that many newest
292	// samples. Lowering the limit trims the oldest events immediately by receive
293	// sequence; raising it only affects future writes. Device activity, last
294	// telemetry, alerts and other devices are untouched.
295	func (s *Store) SetRetention(id string, maxEvents int64) (RetentionStatus, error) {
296		s.mu.Lock()
297		defer s.mu.Unlock()
298		state, ok := s.devices[id]
299		if !ok {
300			return RetentionStatus{}, ErrDeviceNotFound
301		}
302		trimThrough := planTrimThrough(state.eventBase, state.maxSequence(), maxEvents)
303		if s.wal != nil {
304			if err := s.wal.appendRecord(recRetention, walRetention{
305				DeviceID:    id,
306				MaxEvents:   maxEvents,
307				TrimThrough: trimThrough,
308			}); err != nil {
309				return RetentionStatus{}, storageUnavailable(err)
310			}
311		}
312		state.maxEvents = maxEvents
313		state.applyTrim(trimThrough)
314		return state.retentionStatus(), nil
315	}
316	
317	// RecordTelemetry stores a live telemetry sample in the device history. The
318	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
319	// observed time is the server receive time.
320	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
321		s.mu.Lock()
322		defer s.mu.Unlock()
323		state, ok := s.devices[id]
324		if !ok {
325			return Device{}, ErrDeviceNotFound
326		}
327		now := s.now().UTC()
328		sequence := state.maxSequence() + 1
329		trimThrough := planTrimThrough(state.eventBase, sequence, state.maxEvents)
330		eval := newAlertEvaluator(state)
331		eval.evaluate(sequence, now, values)
332		if s.wal != nil {
333			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
334				DeviceID:    id,
335				Sequence:    sequence,
336				ObservedAt:  now,
337				Values:      values,
338				TrimThrough: trimThrough,
339				Alerts:      eval.created,
340				Ended:       eval.ended,
341			}); err != nil {
342				return Device{}, storageUnavailable(err)
343			}
344		}
345		state.events = append(state.events, Event{
346			Sequence:   sequence,
347			ObservedAt: now,
348			Values:     cloneTelemetry(values),
349		})
350		state.device.LastSeenAt = now
351		state.device.LastTelemetry = cloneTelemetry(values)
352		eval.commit()
353		state.applyTrim(trimThrough)
354		return cloneDevice(state.device), nil
355	}
356	
357	// Replay validates and commits a batch atomically. repeat is true when the
358	// batchId was already committed with identical content and the first receipt
359	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
360	// ErrBatchConflict when any sample clashes with an existing eventId or the
361	// batchId was previously committed with different ordered content; in either
362	// conflict case no state changes.
363	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
364		s.mu.Lock()
365		defer s.mu.Unlock()
366		state, ok := s.devices[id]
367		if !ok {
368			return ReplayReceipt{}, false, ErrDeviceNotFound
369		}
370	
371		if previous, exists := state.batches[batchID]; exists {
372			if !sameOrderedSamples(previous.samples, samples) {
373				return ReplayReceipt{}, false, ErrBatchConflict
374			}
375			return cloneReceipt(previous.receipt), true, nil
376		}
377	
378		// Validate every sample against the device's dedup memory before assigning
379		// anything, so a conflict rolls back without leaving sequences, events or
380		// receipts. A previously trimmed event is still known here: identical
381		// content stays a duplicate (and never re-enters history), different
382		// content still conflicts the whole batch.
383		type plan struct {
384			sample   Sample
385			sequence int64
386			dup      bool
387		}
388		planned := make([]plan, len(samples))
389		nextSequence := state.maxSequence() + 1
390		for i, sample := range samples {
391			if known, seen := state.known[sample.EventID]; seen {
392				if !sameInstant(known.observedAt, sample.ObservedAt) ||
393					!sameValues(known.values, sample.Values) {
394					return ReplayReceipt{}, false, ErrBatchConflict
395				}
396				planned[i] = plan{sample, known.sequence, true}
397				continue
398			}
399			planned[i] = plan{sample, nextSequence, false}
400			nextSequence++
401		}
402		maxSequence := nextSequence - 1
403		trimThrough := planTrimThrough(state.eventBase, maxSequence, state.maxEvents)
404	
405		// Build the receipt from the plan: only samples that matched a committed
406		// event before this batch are duplicates.
407		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
408		for _, entry := range planned {
409			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
410				EventID:   entry.sample.EventID,
411				Sequence:  entry.sequence,
412				Duplicate: entry.dup,
413			})
414			if entry.dup {
415				receipt.Duplicate++
416			} else {
417				receipt.NewCount++
418			}
419		}
420	
421		// Evaluate the batch's new samples against the device's enabled rules, in
422		// array order (which is receive-sequence order). Duplicates never judge,
423		// create, end or refresh alerts. A trigger and a recovery inside one batch
424		// both produce alert changes, all committed together with the batch.
425		eval := newAlertEvaluator(state)
426		for _, entry := range planned {
427			if entry.dup {
428				continue
429			}
430			eval.evaluate(entry.sequence, entry.sample.ObservedAt, entry.sample.Values)
431		}
432	
433		// Durable commit point: the whole batch is one record, synced before any
434		// in-memory state changes and before success is reported. A failure here
435		// leaves sequences, history, receipts, device state and alert changes
436		// untouched.
437		lastNew := -1
438		for i, entry := range planned {
439			if !entry.dup {
440				lastNew = i
441			}
442		}
443		var committedAt time.Time
444		if s.wal != nil {
445			record := walReplay{
446				DeviceID:    id,
447				BatchID:     batchID,
448				Samples:     make([]walSample, len(samples)),
449				Receipt:     receipt,
450				TrimThrough: trimThrough,
451				Alerts:      eval.created,
452				Ended:       eval.ended,
453			}
454			for i, sample := range samples {
455				record.Samples[i] = walSample{
456					EventID:    sample.EventID,
457					ObservedAt: sample.ObservedAt,
458					Values:     sample.Values,
459				}
460			}
461			if lastNew >= 0 {
462				committedAt = s.now().UTC()
463				record.LastSeenAt = &committedAt
464				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
465			}
466			if err := s.wal.appendRecord(recReplay, record); err != nil {
467				return ReplayReceipt{}, false, storageUnavailable(err)
468			}
469		}
470	
471		// Commit: append new samples in array order. Every new sample registers in
472		// the durable dedup memory, even when the retention limit immediately
473		// trims its event out of history.
474		for _, entry := range planned {
475			if entry.dup {
476				continue
477			}
478			state.events = append(state.events, Event{
479				Sequence:   entry.sequence,
480				ObservedAt: entry.sample.ObservedAt,
481				Values:     cloneTelemetry(entry.sample.Values),
482			})
483			state.known[entry.sample.EventID] = knownSample{
484				sequence:   entry.sequence,
485				observedAt: entry.sample.ObservedAt,
486				values:     cloneTelemetry(entry.sample.Values),
487			}
488		}
489	
490		committed := make([]Sample, len(samples))
491		copy(committed, samples)
492		for i := range committed {
493			committed[i].Values = cloneTelemetry(samples[i].Values)
494		}
495		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
496	
497		if lastNew >= 0 {
498			if s.wal == nil {
499				committedAt = s.now().UTC()
500			}
501			state.device.LastSeenAt = committedAt
502			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
503		}
504		eval.commit()
505		// Enforce the retention limit after the whole batch is accepted: all new
506		// samples judged, kept their assigned sequences and appear on the receipt;
507		// only the oldest excess events leave history.
508		state.applyTrim(trimThrough)
509		return receipt, false, nil
510	}
511	
512	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
513		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
514		return receipt
515	}
516	
517	// --- rules and alerts -------------------------------------------------------
518	
519	// ruleUpdate carries the mutable fields of a rule update. A nil pointer leaves
520	// the field unchanged.
521	type ruleUpdate struct {
522		Metric  *string
523		Trigger *float64
524		Recover *float64
525		Enabled *bool
526	}
527	
528	// AlertFilter narrows an alert listing. An empty string or nil pointer leaves
529	// that dimension unfiltered.
530	type AlertFilter struct {
531		RuleID       string
532		Status       string
533		Acknowledged *bool
534	}
535	
536	// CreateRule registers a new enabled rule on a device. Version starts at 1.
537	// It returns ErrDeviceNotFound for an unknown device and ErrRuleConflict when
538	// the device already has a rule with that id.
539	func (s *Store) CreateRule(id, ruleID, metric string, trigger, recover float64) (Rule, error) {
540		s.mu.Lock()
541		defer s.mu.Unlock()
542		state, ok := s.devices[id]
543		if !ok {
544			return Rule{}, ErrDeviceNotFound
545		}
546		if _, exists := state.rules[ruleID]; exists {
547			return Rule{}, ErrRuleConflict
548		}
549		now := s.now().UTC()
550		rule := Rule{
551			ID: ruleID, Metric: metric, Trigger: trigger, Recover: recover,
552			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
553		}
554		if s.wal != nil {
555			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: rule}); err != nil {
556				return Rule{}, storageUnavailable(err)
557			}
558		}
559		state.rules[ruleID] = &ruleState{rule: rule}
560		return cloneRule(rule), nil
561	}
562	
563	// UpdateRule applies a version-checked optimistic update. A version mismatch
564	// returns ErrVersionConflict with state unchanged. Every successful update
565	// bumps the version by one and immediately ends the rule's active alert (if
566	// any) with reason rule_changed; the rule starts again with no active alert.
567	func (s *Store) UpdateRule(id, ruleID string, update ruleUpdate, version int64) (Rule, []*Alert, error) {
568		s.mu.Lock()
569		defer s.mu.Unlock()
570		state, ok := s.devices[id]
571		if !ok {
572			return Rule{}, nil, ErrDeviceNotFound
573		}
574		rs, ok := state.rules[ruleID]
575		if !ok {
576			return Rule{}, nil, ErrRuleNotFound
577		}
578		if rs.rule.Version != version {
579			return Rule{}, nil, ErrVersionConflict
580		}
581	
582		updated := rs.rule
583		if update.Metric != nil {
584			updated.Metric = *update.Metric
585		}
586		if update.Trigger != nil {
587			updated.Trigger = *update.Trigger
588		}
589		if update.Recover != nil {
590			updated.Recover = *update.Recover
591		}
592		if update.Enabled != nil {
593			updated.Enabled = *update.Enabled
594		}
595		if updated.Recover >= updated.Trigger {
596			return Rule{}, nil, ErrInvalidRule
597		}
598	
599		// End the active alert of the old version before publishing the new one.
600		var ended []*Alert
601		if rs.activeAlertID != 0 {
602			alert := cloneAlert(*state.alerts[rs.activeAlertID-1])
603			alert.Status = alertStatusEnded
604			alert.EndReason = endReasonRuleChanged
605			now := s.now().UTC()
606			alert.EndedAt = &now
607			ended = append(ended, &alert)
608			rs.activeAlertID = 0
609		}
610	
611		updated.Version++
612		updated.UpdatedAt = s.now().UTC()
613	
614		if s.wal != nil {
615			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: updated, Ended: ended}); err != nil {
616				return Rule{}, nil, storageUnavailable(err)
617			}
618		}
619		rs.rule = updated
620		for _, alert := range ended {
621			state.alerts[alert.ID-1] = alert
622		}
623		return cloneRule(updated), cloneAlerts(ended), nil
624	}
625	
626	// GetRule returns one rule.
627	func (s *Store) GetRule(id, ruleID string) (Rule, error) {
628		s.mu.RLock()
629		defer s.mu.RUnlock()
630		state, ok := s.devices[id]
631		if !ok {
632			return Rule{}, ErrDeviceNotFound
633		}
634		rs, ok := state.rules[ruleID]
635		if !ok {
636			return Rule{}, ErrRuleNotFound
637		}
638		return cloneRule(rs.rule), nil
639	}
640	
641	// ListRules returns a device's rules, ordered by rule id.
642	func (s *Store) ListRules(id string) ([]Rule, error) {
643		s.mu.RLock()
644		defer s.mu.RUnlock()
645		state, ok := s.devices[id]
646		if !ok {
647			return nil, ErrDeviceNotFound
648		}
649		rules := make([]Rule, 0, len(state.rules))
650		for _, rs := range state.rules {
651			rules = append(rules, cloneRule(rs.rule))
652		}
653		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
654		return rules, nil
655	}
656	
657	// AckAlert records the server time of the first acknowledgment. Repeated
658	// acknowledgments keep the original time and write nothing. It returns
659	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
660	// alert id.
661	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
662		s.mu.Lock()
663		defer s.mu.Unlock()
664		state, ok := s.devices[id]
665		if !ok {
666			return Alert{}, ErrDeviceNotFound
667		}
668		if alertID < 1 || int(alertID) > len(state.alerts) {
669			return Alert{}, ErrAlertNotFound
670		}
671		alert := state.alerts[alertID-1]
672		if alert.AcknowledgedAt != nil {
673			return cloneAlert(*alert), nil
674		}
675		now := s.now().UTC()
676		if s.wal != nil {
677			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
678				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
679			}); err != nil {
680				return Alert{}, storageUnavailable(err)
681			}
682		}
683		alert.AcknowledgedAt = &now
684		return cloneAlert(*alert), nil
685	}
686	
687	// ListAlerts returns a device's alerts with the given filters, ordered by
688	// alert id.
689	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
690		s.mu.RLock()
691		defer s.mu.RUnlock()
692		state, ok := s.devices[id]
693		if !ok {
694			return nil, ErrDeviceNotFound
695		}
696		if filter.RuleID != "" {
697			if _, ok := state.rules[filter.RuleID]; !ok {
698				return nil, ErrRuleNotFound
699			}
700		}
701		alerts := make([]Alert, 0, len(state.alerts))
702		for _, alert := range state.alerts {
703			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
704				continue
705			}
706			if filter.Status != "" && alert.Status != filter.Status {
707				continue
708			}
709			if filter.Acknowledged != nil {
710				acknowledged := alert.AcknowledgedAt != nil
711				if *filter.Acknowledged != acknowledged {
712					continue
713				}
714			}
715			alerts = append(alerts, cloneAlert(*alert))
716		}
717		return alerts, nil
718	}
719	
720	// alertEvaluator applies accepted samples to a device's enabled rules without
721	// mutating state until commit. It tracks which rule currently has an active
722	// alert so a trigger and a recovery inside the same batch are both handled in
723	// order.
724	type alertEvaluator struct {
725		state        *deviceState
726		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
727		created      []*Alert
728		ended        []*Alert
729		nextID       int64
730	}
731	
732	func newAlertEvaluator(state *deviceState) *alertEvaluator {
733		eval := &alertEvaluator{
734			state:        state,
735			activeByRule: make(map[string]int64, len(state.rules)),
736			nextID:       int64(len(state.alerts)) + 1,
737		}
738		for id, rs := range state.rules {
739			eval.activeByRule[id] = rs.activeAlertID
740		}
741		return eval
742	}
743	
744	// evaluate judges one accepted sample. A value at or above the trigger opens
745	// an alert (or keeps the existing one); a value at or below the recovery
746	// threshold ends the active alert; anything in between or a missing metric
747	// leaves state unchanged.
748	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
749		for _, rs := range eval.state.rules {
750			if !rs.rule.Enabled {
751				continue
752			}
753			value, ok := values[rs.rule.Metric]
754			if !ok {
755				continue
756			}
757			activeID := eval.activeByRule[rs.rule.ID]
758			if value >= rs.rule.Trigger && activeID == 0 {
759				alert := &Alert{
760					ID:                eval.nextID,
761					RuleID:            rs.rule.ID,
762					RuleVersion:       rs.rule.Version,
763					Metric:            rs.rule.Metric,
764					Trigger:           rs.rule.Trigger,
765					Recover:           rs.rule.Recover,
766					Status:            alertStatusActive,
767					TriggerSequence:   seq,
768					TriggerValue:      value,
769					TriggerObservedAt: observedAt,
770				}
771				eval.nextID++
772				eval.created = append(eval.created, alert)
773				eval.activeByRule[rs.rule.ID] = alert.ID
774			} else if value <= rs.rule.Recover && activeID != 0 {
775				var source *Alert
776				if activeID <= int64(len(eval.state.alerts)) {
777					source = eval.state.alerts[activeID-1]
778				} else {
779					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
780				}
781				alert := cloneAlert(*source)
782				alert.Status = alertStatusEnded
783				alert.EndReason = endReasonRecovered
784				alert.RecoverSequence = &seq
785				alert.RecoverValue = &value
786				alert.RecoverObservedAt = &observedAt
787				eval.ended = append(eval.ended, &alert)
788				eval.activeByRule[rs.rule.ID] = 0
789			}
790		}
791	}
792	
793	// commit publishes the planned alert changes to the device state.
794	func (eval *alertEvaluator) commit() {
795		applyAlertChanges(eval.state, eval.created, eval.ended)
796	}
797	
798	// applyAlertChanges appends created alerts and replaces ended ones, keeping
799	// each rule's active-alert pointer in sync. It is shared by live evaluation
800	// and WAL recovery.
801	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
802		for _, alert := range created {
803			state.alerts = append(state.alerts, alert)
804			if rs, ok := state.rules[alert.RuleID]; ok {
805				rs.activeAlertID = alert.ID
806			}
807		}
808		for _, alert := range ended {
809			state.alerts[alert.ID-1] = alert
810			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
811				rs.activeAlertID = 0
812			}
813		}
814	}
815	
816	func cloneRule(rule Rule) Rule {
817		return rule
818	}
819	
820	func cloneAlert(alert Alert) Alert {
821		if alert.RecoverSequence != nil {
822			seq := *alert.RecoverSequence
823			alert.RecoverSequence = &seq
824		}
825		if alert.RecoverValue != nil {
826			value := *alert.RecoverValue
827			alert.RecoverValue = &value
828		}
829		if alert.RecoverObservedAt != nil {
830			t := *alert.RecoverObservedAt
831			alert.RecoverObservedAt = &t
832		}
833		if alert.EndedAt != nil {
834			t := *alert.EndedAt
835			alert.EndedAt = &t
836		}
837		if alert.AcknowledgedAt != nil {
838			t := *alert.AcknowledgedAt
839			alert.AcknowledgedAt = &t
840		}
841		return alert
842	}
843	
844	func cloneAlerts(alerts []*Alert) []*Alert {
845		if alerts == nil {
846			return nil
847		}
848		cloned := make([]*Alert, len(alerts))
849		for i, alert := range alerts {
850			c := cloneAlert(*alert)
851			cloned[i] = &c
852		}
853		return cloned
854	}
855	
856	// historyGoneError carries the current earliest retained sequence alongside
857	// ErrHistoryGone so a 410 response can tell the client where the surviving
858	// history resumes.
859	type historyGoneError struct {
860		earliestSequence int64
861	}
862	
863	func (e *historyGoneError) Error() string { return ErrHistoryGone.Error() }
864	func (e *historyGoneError) Unwrap() error { return ErrHistoryGone }
865	
866	// History returns one page of a device's event history. startSeq is the first
867	// receive sequence to scan (1 or 0 for the first page, which begins at the
868	// current earliest retained event); limit caps the number of matching events
869	// returned. bound pins the scan to sequences no larger than bound; a zero
870	// bound means "current maximum", which is then returned so callers can pin
871	// subsequent pages. nextStart is the sequence a following page should start at
872	// when hasMore is true. Retention may have removed the start of a continuation
873	// page: then ErrHistoryGone is returned with the current earliest sequence, so
874	// the missing range is never skipped silently. Concurrent writes cannot skip
875	// or duplicate rows within a paged walk.
876	func (s *Store) History(id string, filter HistoryFilter, startSeq, bound int64, limit int) (events []Event, appliedBound, nextStart int64, hasMore bool, err error) {
877		s.mu.RLock()
878		defer s.mu.RUnlock()
879		state, ok := s.devices[id]
880		if !ok {
881			return nil, 0, 0, false, ErrDeviceNotFound
882		}
883		highWater := state.maxSequence()
884		if bound == 0 {
885			bound = highWater
886		}
887		continuation := startSeq > 0
888		if !continuation {
889			startSeq = state.earliestSequence()
890			if startSeq == 0 {
891				startSeq = 1
892			}
893		} else if startSeq < state.earliestSequence() || startSeq > state.maxSequence() {
894			// The exact record the continuation starts at (or a prefix containing
895			// it) was trimmed. Report 410 with the live window's first sequence
896			// instead of silently resuming partway through the pinned range.
897			return nil, bound, 0, false, &historyGoneError{earliestSequence: state.earliestSequence()}
898		}
899		events = make([]Event, 0, limit)
900		for seq := startSeq; seq <= bound; seq++ {
901			event := state.events[seq-1-state.eventBase]
902			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
903				continue
904			}
905			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
906				continue
907			}
908			if len(events) < limit {
909				events = append(events, cloneEvent(event))
910				continue
911			}
912			// This match belongs to the next page; resume scanning at its sequence
913			// so rows in the gap are never examined twice.
914			return events, bound, seq, true, nil
915		}
916		return events, bound, 0, false, nil
917	}
918	
919	func (s *Store) Snapshot() []Device {
920		s.mu.RLock()
921		defer s.mu.RUnlock()
922		result := make([]Device, 0, len(s.devices))
923		for _, state := range s.devices {
924			result = append(result, cloneDevice(state.device))
925		}
926		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
927		return result
928	}
929	
930	func cloneDevice(device Device) Device {
931		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
932		return device
933	}
934	
935	func cloneEvent(event Event) Event {
936		event.Values = cloneTelemetry(event.Values)
937		return event
938	}
939	
940	func cloneTelemetry(values map[string]float64) map[string]float64 {
941		if values == nil {
942			return nil
943		}
944		cloned := make(map[string]float64, len(values))
945		for key, value := range values {
946			cloned[key] = value
947		}
948		return cloned
949	}
950	
951	// sameInstant compares times as UTC instants.
952	func sameInstant(a, b time.Time) bool {
953		return a.UTC().Equal(b.UTC())
954	}
955	
956	// sameValues compares metric maps by key and value.
957	func sameValues(a, b map[string]float64) bool {
958		if len(a) != len(b) {
959			return false
960		}
961		for key, value := range a {
962			other, ok := b[key]
963			if !ok || value != other {
964				return false
965			}
966		}
967		return true
968	}
969	
970	// sameOrderedSamples reports whether two batches carry the same samples in the
971	// same order, compared as UTC instants and key/value maps.
972	func sameOrderedSamples(a, b []Sample) bool {
973		if len(a) != len(b) {
974			return false
975		}
976		for i := range a {
977			if a[i].EventID != b[i].EventID ||
978				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
979				!sameValues(a[i].Values, b[i].Values) {
980				return false
981			}
982		}
983		return true
984	}
