28		mux.HandleFunc("GET /v1/devices/{id}/history/retention", h.getRetention)
29		mux.HandleFunc("PUT /v1/devices/{id}/history/retention", h.setRetention)
30		mux.HandleFunc("GET /v1/fleet", h.snapshot)
31		mux.HandleFunc("POST /v1/devices/{id}/rules", h.createRule)
32		mux.HandleFunc("GET /v1/devices/{id}/rules", h.listRules)
33		mux.HandleFunc("GET /v1/devices/{id}/rules/{ruleId}", h.getRule)
34		mux.HandleFunc("PUT /v1/devices/{id}/rules/{ruleId}", h.updateRule)
35		mux.HandleFunc("POST /v1/devices/{id}/alerts/{alertId}/acknowledge", h.ackAlert)
36		mux.HandleFunc("GET /v1/devices/{id}/alerts", h.listAlerts)
