func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
	if raw := strings.TrimSpace(query.Get("status")); raw != "" {
		if raw != alertStatusActive && raw != alertStatusEnded {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
			return
		}
		filter.Status = raw
	}
	if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
		switch raw {
		case "true", "1":
			v := true
			filter.Acknowledged = &v
		case "false", "0":
			v := false
			filter.Acknowledged = &v
		default:
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
			return
		}
	}
	alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrRuleNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
}

func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
	alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
	if err != nil || alertID < 1 {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
		return
	}
	alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
	if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, alert)
}

func finiteFloat(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0)
}

func hasBlankKey(values map[string]*float64) bool {
	for key := range values {
		if strings.TrimSpace(key) == "" {
			return true
		}
	}
	return false
}

// metricValues converts decoded metric values to plain floats. Decoding into
// *float64 keeps JSON null distinguishable from a real 0: a null decodes to a
// nil pointer and is rejected here instead of being silently stored as 0.
// Non-finite numbers are rejected as before.
func metricValues(raw map[string]*float64) (map[string]float64, bool) {
	values := make(map[string]float64, len(raw))
	for key, value := range raw {
		if value == nil || !finiteFloat(*value) {
			return nil, false
		}
		values[key] = *value
	}
	return values, true
}

func decodeJSON(r *http.Request, target any) error {
	decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
	decoder.DisallowUnknownFields()
	return decoder.Decode(target)
}

// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
// trailing data such as a second JSON object or concatenated documents.
func decodeSingleJSON(r *http.Request, target any) error {
	decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return err
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return errors.New("body must contain a single JSON value")
	}
	return nil
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

package fleet

import (
	"net/http"
	"testing"
)

// --- restart preserves rules, alerts and ack times ---------------------------

func TestPersistentRestartPreservesRulesAndAlerts(t *testing.T) {
	dir := t.TempDir()
	store := openPersistent(t, dir)
	h := NewHandler(store)
	mustRegister(t, h, "gw")
	createRule(t, h, "gw", "r1", "temperature", 30, 25)

	// Trigger, sustain, recover, then ack.
	doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":32}`)
	doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":33}`)
	doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":24}`)
	doRequest(t, h, http.MethodPost, "/v1/devices/gw/alerts/1/acknowledge", "")

	// Update the rule (version 1 -> 2) with no active alert.
	doRequest(t, h, http.MethodPut, "/v1/devices/gw/rules/r1",
		`{"trigger":35,"recover":28,"version":1}`)

	if err := store.Close(); err != nil {
		t.Fatal(err)
	}
	store2 := reopenPersistent(t, dir)
	h2 := NewHandler(store2)

	// Rule version and config survive.
	rules := listRules(t, h2, "gw")
	if len(rules) != 1 || rules[0].Version != 2 || rules[0].Trigger != 35 ||
		rules[0].Recover != 28 || !rules[0].Enabled {
		t.Fatalf("recovered rule = %+v", rules)
	}

	// Alert, its recovery fields and ack time survive.
	alerts := listAlerts(t, h2, "gw", "")
	if len(alerts) != 1 {
		t.Fatalf("recovered alerts = %+v", alerts)
	}
	alert := alerts[0]
	if alert.ID != 1 || alert.Status != alertStatusEnded ||
		alert.EndReason != endReasonRecovered || alert.TriggerSequence != 1 ||
		alert.TriggerValue != 32 || alert.RecoverSequence == nil ||
		*alert.RecoverSequence != 3 || *alert.RecoverValue != 24 {
		t.Fatalf("recovered alert = %+v", alert)
	}
	if alert.AcknowledgedAt == nil {
		t.Fatalf("ack time lost across restart")
	}

	// No re-trigger on recovery: the active alert count is unchanged.
	active := listAlerts(t, h2, "gw", "status=active")
	if len(active) != 0 {
		t.Fatalf("recovery re-triggered: %+v", active)
	}

	// New samples continue to judge against the recovered rule version.
	doRequest(t, h2, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":40}`)
	alerts = listAlerts(t, h2, "gw", "")
	if len(alerts) != 2 || alerts[1].Status != alertStatusActive ||
		alerts[1].RuleVersion != 2 || alerts[1].TriggerSequence != 4 {
		t.Fatalf("post-restart alert = %+v", alerts[1])
	}
}

