396	func TestAlertAck(t *testing.T) {
397		h := NewHandler(NewStore())
398		mustRegister(t, h, "gw")
399		createRule(t, h, "gw", "r1", "temperature", 30, 25)
400		doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":32}`)
401	
402		// Ack records server time.
403		r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/alerts/1/acknowledge", "")
404		if r.Code != http.StatusOK {
405			t.Fatalf("ack = %d: %s", r.Code, r.Body.String())
406		}
407		first := decodeBody[alertResponse](t, r)
408		if first.AcknowledgedAt == nil {
409			t.Fatalf("acknowledgedAt = nil")
410		}
411		firstTime := *first.AcknowledgedAt
412	
413		// Repeat ack keeps the original time.
414		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/alerts/1/acknowledge", "")
415		if r.Code != http.StatusOK {
416			t.Fatalf("repeat ack = %d", r.Code)
417		}
418		second := decodeBody[alertResponse](t, r)
419		if second.AcknowledgedAt == nil || !second.AcknowledgedAt.Equal(firstTime) {
420			t.Fatalf("repeat ack changed time: %v vs %v", second.AcknowledgedAt, firstTime)
421		}
422	
423		// Ack does not end the alert.
424		alerts := listAlerts(t, h, "gw", "")
425		if len(alerts) != 1 || alerts[0].Status != alertStatusActive {
426			t.Fatalf("ack ended alert: %+v", alerts[0])
427		}
428	
429		// Ack unknown alert -> 404.
430		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/alerts/999/acknowledge", "")
431		if r.Code != http.StatusNotFound {
432			t.Fatalf("unknown alert = %d, want 404", r.Code)
433		}
434		// Ack unknown device -> 404.
435		r = doRequest(t, h, http.MethodPost, "/v1/devices/ghost/alerts/1/acknowledge", "")
436		if r.Code != http.StatusNotFound {
437			t.Fatalf("unknown device = %d, want 404", r.Code)
438		}
